"""Traffic-analysis experiment: how much do pqvpn's length/timing defences hide *which kind of activity* a tunnel
carries, from an on-path observer who sees only encrypted datagram sizes, directions and times?

    PQVPN_LIBCRYPTO=... python research/traffic_analysis/experiment.py [--quick] [--out results.json]

Honest scope (see research/TRAFFIC_ANALYSIS.md):
  * Traces are SYNTHETIC, generated by the workload models below with fixed seeds. No customer traffic, packet
    capture or browsing history is used or collected. Numbers describe these models, not real users.
  * The attacker is a simple, classical one (k-nearest-neighbours and nearest-centroid on 38 hand-made
    features). Stronger attacks (deep learning on packet sequences) will do at least as well; a defence that
    fails here fails in practice, a defence that "wins" here is not thereby proven.
  * Closed world: 6 activity classes, every test trace belongs to one of them.
  * Train/test are split by ENVIRONMENT (network conditions + tunnel MTU), as recommended in the research guide,
    with a same-environment random split reported alongside to show how optimistic that would be.
  * Wire sizes are computed with the production code: pqvpn.session.pad() and a real Keypair.encrypt() of
    the negotiated suite (checked once per size class at start-up).
"""

from __future__ import annotations

import argparse
import json
import math
import os
import random
import statistics
import sys
import time

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

from pqvpn.protocol import DATA_OVERHEAD  # noqa: E402
from pqvpn.session import pad  # noqa: E402

T = 5.0                  # observation window per trace (s)
ACK = 52                 # IPv4 + TCP header with timestamps, no payload
CLASSES = ("web", "video", "voip", "bulk", "chat", "interactive")

# Two network environments.  Everything that differs here is something an attacker cannot control when
# training: link speed, latency, jitter and the tunnel MTU (1420 default vs 1280, common on mobile).
ENVS = {
    "A": {"rtt": 0.020, "bw": 50e6, "mtu": 1420, "jitter": 0.001},
    "B": {"rtt": 0.080, "bw": 8e6, "mtu": 1280, "jitter": 0.004},
}


# ====================================================================== workload models
# A trace is a list of (time_s, direction, ip_length); direction +1 = client->server (up), -1 = down.

def _tcp_transfer(out, rng, env, t0, nbytes, direction, rate_frac=1.0):
    """Bulk TCP transfer: full-MSS segments paced at the link rate, one ACK per two segments the other way."""
    mtu = env["mtu"]
    mss = mtu - 40
    rate = env["bw"] * rate_frac
    t = t0 + env["rtt"] / 2
    n = max(1, math.ceil(nbytes / mss))
    for i in range(n):
        size = mtu if i < n - 1 else 40 + (nbytes - mss * (n - 1))
        t += size * 8 / rate + abs(rng.gauss(0, env["jitter"] / 4))
        if t >= T:
            break
        out.append((t, direction, size))
        if i % 2:
            out.append((t + env["rtt"] / 2, -direction, ACK))
    return t


def gen_web(rng, env):
    out, t = [], rng.uniform(0, 0.5)
    while t < T:
        for _ in range(rng.randint(4, 30)):                       # objects on the page, ~6 parallel streams
            start = t + rng.uniform(0, 0.15) + env["rtt"] * rng.randint(0, 3)
            out.append((start, +1, rng.randint(350, 800)))          # request
            _tcp_transfer(out, rng, env, start, int(rng.lognormvariate(9.3, 1.2)), -1, rng.uniform(0.2, 0.6))
        t += 0.3 + rng.expovariate(1 / 2.5)                         # think time
    return out


def gen_video(rng, env):
    out, t = [], rng.uniform(0, 0.3)
    bitrate = min(rng.uniform(1.5e6, 5e6), env["bw"] * 0.7)
    seg = rng.choice((2.0, 4.0))
    first = True
    while t < T:
        out.append((t, +1, rng.randint(400, 600)))
        end = _tcp_transfer(out, rng, env, t, int(bitrate * seg / 8), -1, 0.9)
        t = end + (0.05 if first else max(0.1, seg - (end - t)))
        first = t < 1.5                                             # start-up buffering, then steady state
    return out


def gen_voip(rng, env):
    out = []
    for direction in (+1, -1):
        t, talking = rng.uniform(0, 0.02), rng.random() < 0.5
        until = t + rng.expovariate(1 / 1.5)
        while t < T:
            if talking:
                out.append((t + rng.gauss(0, env["jitter"]), direction, rng.randint(100, 180)))
                t += 0.020
            else:
                out.append((t, direction, 60))                       # comfort-noise frame (DTX)
                t += 0.400
            if t >= until:
                talking, until = not talking, t + rng.expovariate(1 / 1.5)
    return out


def gen_bulk(rng, env):
    out = []
    _tcp_transfer(out, rng, env, rng.uniform(0, 0.2), 10 ** 9, rng.choice((-1, -1, +1)), rng.uniform(0.5, 0.95))
    return out


def gen_chat(rng, env):
    out, t = [], rng.uniform(0, 1)
    while t < T:
        d = rng.choice((+1, -1))
        out.append((t, d, rng.randint(120, 700)))
        out.append((t + env["rtt"] / 2, -d, ACK))
        if rng.random() < 0.08:                                     # a photo now and then
            _tcp_transfer(out, rng, env, t, rng.randint(40_000, 300_000), d, 0.5)
        t += rng.expovariate(1 / 1.2)
    return out


def gen_interactive(rng, env):
    out, t = [], rng.uniform(0, 0.5)
    while t < T:
        for _ in range(rng.randint(2, 12)):                          # a word typed
            out.append((t, +1, rng.randint(88, 112)))
            out.append((t + env["rtt"], -1, rng.randint(88, 112)))  # echo
            out.append((t + env["rtt"] * 1.5, +1, ACK))
            t += rng.lognormvariate(-2.0, 0.5)
        if rng.random() < 0.3:                                       # command output
            for i in range(rng.randint(1, 25)):
                out.append((t + env["rtt"] + i * 0.002, -1, rng.randint(100, env["mtu"])))
        t += rng.expovariate(1 / 0.8)
    return out


GENERATORS = dict(zip(CLASSES, (gen_web, gen_video, gen_voip, gen_bulk, gen_chat, gen_interactive)))


def make_trace(cls, env_name, seed):
    rng = random.Random(f"{cls}/{env_name}/{seed}")
    env = ENVS[env_name]
    tr = [(t, d, min(max(n, 28), env["mtu"])) for t, d, n in GENERATORS[cls](rng, env) if 0 <= t < T]
    tr.sort()
    return tr


# ====================================================================== defences
# Each maps an IP-packet trace to what the observer sees: (time, direction, UDP payload length on the wire),
# plus cost accounting.  Padding defences change only the plaintext length (receivers strip padding by the IP
# header's length field), so they are wire-compatible with unmodified pqvpn peers; cover traffic is not
# (see TRAFFIC_ANALYSIS.md) and is simulated only.

_pad_cache: dict = {}


def wire_pad16(n, mtu):
    """Production behaviour: pqvpn.session.pad() (16-byte multiple, never beyond the MTU) + header + tag."""
    k = (n, mtu)
    if k not in _pad_cache:
        _pad_cache[k] = len(pad(bytes(n), mtu)) + DATA_OVERHEAD
    return _pad_cache[k]


def wire_none(n, mtu):
    return n + DATA_OVERHEAD                                       # reference only: what no padding would reveal


BUCKETS = (128, 256, 512, 1024)


def wire_bucket(n, mtu):
    for b in BUCKETS:
        if n <= b <= mtu:
            return b + DATA_OVERHEAD
    return mtu + DATA_OVERHEAD


def wire_mtu(n, mtu):
    return mtu + DATA_OVERHEAD


def apply_padding(trace, mtu, fn):
    return [(t, d, fn(n, mtu)) for t, d, n in trace], {"added_latency_s": []}


def apply_constant_rate(trace, mtu, rate_up=50.0, rate_down=200.0):
    """Constant-rate cover: each direction sends one MTU-sized datagram per slot; a real packet if one is queued,
    otherwise a dummy.  Real packets wait for the next free slot (that waiting is the latency cost)."""
    seen, delays, backlog = [], [], 0
    for d, rate in ((+1, rate_up), (-1, rate_down)):
        q = [t for t, dd, _ in trace if dd == d]
        i, slot = 0, 0.0
        while slot < T:
            if i < len(q) and q[i] <= slot:
                delays.append(slot - q[i])
                i += 1
            seen.append((slot, d, mtu + DATA_OVERHEAD))
            slot += 1 / rate
        backlog += len(q) - i
    seen.sort()
    return seen, {"added_latency_s": delays, "undelivered": backlog}


DEFENCES = {
    "none (reference)": lambda tr, mtu: apply_padding(tr, mtu, wire_none),
    "pad16 (production)": lambda tr, mtu: apply_padding(tr, mtu, wire_pad16),
    "bucket 128/256/512/1024/MTU": lambda tr, mtu: apply_padding(tr, mtu, wire_bucket),
    "pad to MTU": lambda tr, mtu: apply_padding(tr, mtu, wire_mtu),
    "constant-rate cover 50/200 pps (simulated)": apply_constant_rate,
    "constant-rate cover 400/1600 pps (simulated)": lambda tr, mtu: apply_constant_rate(tr, mtu, 400.0, 1600.0),
}


def validate_wire_sizes():
    """Check the size model against the real data plane: encrypt padded packets with a real Keypair."""
    from research.benchmarks.bench_dataplane import drive
    from pqvpn import pki
    from pqvpn.crypto.suites import SUITES_BY_NAME
    from pqvpn.handshake import Initiator, Policy, Responder
    from pqvpn.runner import TestPKI
    from pqvpn.session import Keypair, unpad
    from pqvpn.runner import icmp_echo
    tp = TestPKI(ca_alg="SLH-DSA-SHA2-128s")
    srv = tp.identity(pki.ROLE_SERVER, "vpn.test", ["10.66.0.1/24"])
    cli = tp.identity(pki.ROLE_CLIENT, "alice", ["10.66.0.2/32"])
    checked = 0
    for name in ("MLKEM768-X25519_CHACHA20POLY1305_SHA384", "MLKEM768-X25519_AES256GCM_SHA384"):
        s = SUITES_BY_NAME[name]
        ri, rr = drive(Initiator(cli, tp.trust(), Policy((s,)), "vpn.test"),
                       Responder(srv, tp.trust(), Policy((s,)), lambda c: {}))
        tx, rx = Keypair(ri, 0), Keypair(rr, 0)
        for mtu in (1280, 1420):
            for n in (28, 52, 100, 129, 257, 600, 1000, 1025, 1279, 1280):
                if n > mtu:
                    continue
                pkt = icmp_echo("10.66.0.2", "10.66.0.1", 1, bytes(n - 28))
                assert len(tx.encrypt(pad(pkt, mtu))) == wire_pad16(n, mtu)
                padded = pkt + bytes(wire_bucket(n, mtu) - DATA_OVERHEAD - n)   # bucket padding, real AEAD
                dg = tx.encrypt(padded)
                assert len(dg) == wire_bucket(n, mtu)
                assert unpad(rx.decrypt(dg)[1]) == pkt                          # receiver recovers the packet
                checked += 1
    return checked


# ====================================================================== features and classifiers

SIZE_BINS = (100, 200, 400, 700, 1000, 1200, 1300, 10 ** 9)


def features(seen):
    f = []
    times = [t for t, _, _ in seen]
    for d in (+1, -1):
        sizes = [n for _, dd, n in seen if dd == d]
        cnt = len(sizes)
        f += [math.log1p(cnt), math.log1p(sum(sizes))]
        hist = [0] * len(SIZE_BINS)
        for n in sizes:
            for i, b in enumerate(SIZE_BINS):
                if n <= b:
                    hist[i] += 1
                    break
        f += [h / cnt if cnt else 0 for h in hist]
        f += [statistics.fmean(sizes) / 1500 if cnt else 0, (statistics.pstdev(sizes) / 1500) if cnt > 1 else 0,
              math.log1p(len(set(sizes)))]
        ts = [t for t, dd, _ in seen if dd == d]
        gaps = [b - a for a, b in zip(ts, ts[1:])]
        if gaps:
            gs = sorted(gaps)
            f += [math.log10(gs[len(gs) // 2] + 1e-6), math.log10(gs[(len(gs) * 9) // 10] + 1e-6),
                  sum(g < 0.001 for g in gaps) / len(gaps)]
        else:
            f += [math.log10(T), math.log10(T), 0.0]
    up = sum(1 for _, d, _ in seen if d > 0)
    f.append(up / len(seen) if seen else 0.5)
    bursts, cur, prev = [], 0, None
    for _, d, _ in seen:
        if d == prev:
            cur += 1
        else:
            if cur:
                bursts.append(cur)
            cur, prev = 1, d
    if cur:
        bursts.append(cur)
    f += [math.log1p(len(bursts)), math.log1p(statistics.fmean(bursts)) if bursts else 0,
          math.log1p(max(bursts)) if bursts else 0]
    per_s = [0] * int(T)
    for t in times:
        per_s[min(int(t), int(T) - 1)] += 1
    f += [math.log1p(statistics.pstdev(per_s)), (times[-1] - times[0]) / T if len(times) > 1 else 0]
    assert len(f) == 38      # SIZE_IDX / NON_SIZE_IDX below depend on this layout
    return f


# Feature groups, for the ablation (indices into features()): per direction a block of 16 =
# [count, bytes] volume, [8 size-histogram bins, mean, std, distinct sizes] size, [3 gap statistics] timing;
# then up-share (volume), 3 burst statistics (ordering), per-second std and active span (timing/volume).
SIZE_IDX = [b + i for b in (0, 16) for i in range(2, 13)]
NON_SIZE_IDX = [i for i in range(38) if i not in SIZE_IDX]


def standardiser(rows):
    cols = list(zip(*rows))
    mu = [statistics.fmean(c) for c in cols]
    sd = [statistics.pstdev(c) or 1.0 for c in cols]
    return lambda r: [(x - m) / s for x, m, s in zip(r, mu, sd)]


def knn(train, k=5):
    z = standardiser([x for x, _ in train])
    pts = [(z(x), y) for x, y in train]

    def predict(x):
        q = z(x)
        best = sorted(((sum((a - b) ** 2 for a, b in zip(q, p)), y) for p, y in pts))[:k]
        votes: dict = {}
        for dist, y in best:
            votes[y] = votes.get(y, 0) + 1
        top = max(votes.values())
        return next(y for _, y in best if votes[y] == top)        # tie -> the nearest of the tied classes
    return predict


def nearest_centroid(train):
    z = standardiser([x for x, _ in train])
    cent = {}
    for c in CLASSES:
        rows = [z(x) for x, y in train if y == c]
        cent[c] = [statistics.fmean(col) for col in zip(*rows)]

    def predict(x):
        q = z(x)
        return min(CLASSES, key=lambda c: sum((a - b) ** 2 for a, b in zip(q, cent[c])))
    return predict


def metrics(pairs):
    """Per-class precision / recall / F1 / FPR, macro averages, accuracy and the confusion matrix."""
    cm = {a: {p: 0 for p in CLASSES} for a in CLASSES}
    for actual, pred in pairs:
        cm[actual][pred] += 1
    total = len(pairs)
    per = {}
    for c in CLASSES:
        tp = cm[c][c]
        fp = sum(cm[a][c] for a in CLASSES if a != c)
        fn = sum(cm[c][p] for p in CLASSES if p != c)
        tn = total - tp - fp - fn
        prec = tp / (tp + fp) if tp + fp else 0.0
        rec = tp / (tp + fn) if tp + fn else 0.0
        per[c] = {"precision": prec, "recall": rec, "f1": 2 * prec * rec / (prec + rec) if prec + rec else 0.0,
                  "fpr": fp / (fp + tn) if fp + tn else 0.0}
    macro = {m: statistics.fmean(per[c][m] for c in CLASSES) for m in ("precision", "recall", "f1", "fpr")}
    return {"accuracy": sum(cm[c][c] for c in CLASSES) / total, "macro": macro, "per_class": per,
            "confusion": cm, "n": total}


# ====================================================================== experiment

def run(n_per_class, seed=1):
    t_start = time.perf_counter()
    raw = {e: [(c, make_trace(c, e, seed * 100000 + i)) for c in CLASSES for i in range(n_per_class)] for e in ENVS}
    res = {"defences": {}}
    for dname, defence in DEFENCES.items():
        data, cost = {}, {"wire_bytes": 0, "ip_bytes": 0, "pad16_bytes": 0, "latency": [], "undelivered": 0,
                          "packets_real": 0, "datagrams_seen": 0}
        per_class = {c: [0, 0] for c in CLASSES}                    # wire bytes, pad16 bytes
        for e, traces in raw.items():
            mtu = ENVS[e]["mtu"]
            rows = []
            for c, tr in traces:
                seen, extra = defence(tr, mtu)
                rows.append((features(seen), c))
                w, p16 = sum(n for _, _, n in seen), sum(wire_pad16(n, mtu) for _, _, n in tr)
                per_class[c][0] += w
                per_class[c][1] += p16
                cost["wire_bytes"] += w
                cost["ip_bytes"] += sum(n for _, _, n in tr)
                cost["pad16_bytes"] += p16
                cost["latency"] += extra["added_latency_s"]
                cost["undelivered"] += extra.get("undelivered", 0)
                cost["packets_real"] += len(tr)
                cost["datagrams_seen"] += len(seen)
            data[e] = rows
        out = {}
        for clf_name, clf in (("kNN (k=5)", knn), ("nearest centroid", nearest_centroid)):
            cross = []
            per_dir = {}
            for tr_e, te_e in (("A", "B"), ("B", "A")):
                predict = clf(data[tr_e])
                pairs = [(y, predict(x)) for x, y in data[te_e]]
                cross += pairs
                per_dir[f"train {tr_e} -> test {te_e}"] = metrics(pairs)["macro"]["f1"]
            rnd = random.Random(seed)
            rows = data["A"][:]
            rnd.shuffle(rows)
            half = len(rows) // 2
            predict = clf(rows[:half])
            same = metrics([(y, predict(x)) for x, y in rows[half:]])
            out[clf_name] = {"cross_environment": metrics(cross), "cross_environment_f1_by_direction": per_dir,
                             "same_environment_random_split": {"accuracy": same["accuracy"], "macro": same["macro"]}}
        ablation = {}
        for group, idx in (("size features only", SIZE_IDX), ("timing/volume/order features only", NON_SIZE_IDX)):
            sub = {e: [([x[i] for i in idx], y) for x, y in rows] for e, rows in data.items()}
            pairs = []
            for tr_e, te_e in (("A", "B"), ("B", "A")):
                predict = knn(sub[tr_e])
                pairs += [(y, predict(x)) for x, y in sub[te_e]]
            ablation[group] = metrics(pairs)["macro"]["f1"]
        lat = sorted(cost["latency"])
        res["defences"][dname] = {
            "classifiers": out,
            "knn_cross_env_f1_feature_ablation": ablation,
            "cost": {
                "wire_bytes_vs_pad16_pct_by_class": {c: 100 * (w / p - 1) for c, (w, p) in per_class.items()},
                "wire_bytes_vs_pad16_pct": 100 * (cost["wire_bytes"] / cost["pad16_bytes"] - 1),
                "wire_bytes_vs_ip_pct": 100 * (cost["wire_bytes"] / cost["ip_bytes"] - 1),
                "datagrams_seen_vs_real_packets": cost["datagrams_seen"] / cost["packets_real"],
                "added_latency_ms_median": 1000 * lat[len(lat) // 2] if lat else 0.0,
                "added_latency_ms_p95": 1000 * lat[(len(lat) * 95) // 100] if lat else 0.0,
                "real_packets_not_sent_within_window_pct": 100 * cost["undelivered"] / cost["packets_real"],
            },
        }
    res["elapsed_s"] = time.perf_counter() - t_start
    return res


def report(runs):
    """Markdown tables: kNN cross-environment macro-F1 as mean [min-max] over seeds, the rest from the first seed."""
    first = runs[0]

    def f1s(d, clf="kNN (k=5)"):
        v = [r["defences"][d]["classifiers"][clf]["cross_environment"]["macro"]["f1"] for r in runs]
        return f"{statistics.fmean(v):.3f} [{min(v):.3f}-{max(v):.3f}]"
    lines = [f"Attack results (closed world, {len(CLASSES)} classes, chance = {1 / len(CLASSES):.3f}; "
             f"cross-environment = train A/test B + train B/test A; {len(runs)} seed(s))", "",
             "| Defence | kNN macro-F1 cross-env | centroid macro-F1 cross-env | kNN accuracy | kNN macro-FPR | "
             "kNN macro-F1 same-env split | kNN F1 sizes only | kNN F1 timing/volume only |",
             "| --- | --- | --- | --- | --- | --- | --- | --- |"]
    for d, r in first["defences"].items():
        k = r["classifiers"]["kNN (k=5)"]
        ab = r["knn_cross_env_f1_feature_ablation"]
        lines.append(f"| {d} | {f1s(d)} | {f1s(d, 'nearest centroid')} | {k['cross_environment']['accuracy']:.3f} | "
                     f"{k['cross_environment']['macro']['fpr']:.3f} | "
                     f"{k['same_environment_random_split']['macro']['f1']:.3f} | "
                     f"{ab['size features only']:.3f} | {ab['timing/volume/order features only']:.3f} |")
    lines += ["", "Cost (first seed)", "",
              "| Defence | bytes vs pad16 (all) | " + " | ".join(f"{c}" for c in CLASSES) +
              " | added latency median / p95 | real packets not sent in window |",
              "| --- | --- | " + " | ".join("---" for _ in CLASSES) + " | --- | --- |"]
    for d, r in first["defences"].items():
        c = r["cost"]
        lines.append(f"| {d} | {c['wire_bytes_vs_pad16_pct']:+.1f} % | " +
                     " | ".join(f"{c['wire_bytes_vs_pad16_pct_by_class'][k]:+.0f} %" for k in CLASSES) +
                     f" | {c['added_latency_ms_median']:.1f} / {c['added_latency_ms_p95']:.1f} ms | "
                     f"{c['real_packets_not_sent_within_window_pct']:.1f} % |")
    return "\n".join(lines)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--quick", action="store_true", help="12 traces per class and environment instead of 50")
    ap.add_argument("--seeds", default="1,2,3", help="comma-separated seeds (each is a fresh set of traces)")
    ap.add_argument("--out")
    a = ap.parse_args(argv)
    checked = validate_wire_sizes()
    print(f"wire-size model checked against real Keypair.encrypt/decrypt: {checked} cases OK", file=sys.stderr)
    n = 12 if a.quick else 50
    seeds = [int(s) for s in a.seeds.split(",")]
    runs = [run(n, s) for s in seeds]
    from research.benchmarks.bench_dataplane import environment
    res = {"setup": {"traces_per_class_per_env": n, "classes": CLASSES, "environments": ENVS, "window_s": T,
                     "seeds": seeds, "wire_size_checks": checked, "chance_accuracy": 1 / len(CLASSES)},
           "environment": environment(), "runs": runs}
    print(report(runs))
    if a.out:
        with open(a.out, "w", encoding="utf-8") as f:
            json.dump(res, f, indent=2)
    return 0


if __name__ == "__main__":
    sys.exit(main())
